    <div class="form-box" style="margin-top:20px;">
        <h3>🔑 Passkeys</h3>
        <p style="margin-top:0;color:#666;">Manage the devices that can unlock your SentryIQ vault with Face ID, Touch ID, or passkey authentication.</p>
        <?php
        $passkeyStore = [];
        $passkeyDataDir = sentryiq_data_dir();
        if ($passkeyDataDir !== '') {
            $passkeyPath = $passkeyDataDir . '/passkeys.json';
            if (is_file($passkeyPath) && !is_link($passkeyPath)) {
                $passkeyRaw = @file_get_contents($passkeyPath);
                $passkeyDecoded = is_string($passkeyRaw) ? json_decode($passkeyRaw, true) : null;
                if (is_array($passkeyDecoded)) $passkeyStore = $passkeyDecoded;
            }
        }
        $passkeyCredentials = is_array($passkeyStore['credentials'] ?? null) ? $passkeyStore['credentials'] : [];
        ?>
        <div id="passkey-message" style="display:none;"></div>
        <?php if (empty($passkeyCredentials)): ?>
            <div style="padding:18px;border:1px solid #e9ecef;border-radius:10px;text-align:center;color:#666;">No passkeys are registered yet.</div>
        <?php else: ?>
            <?php foreach ($passkeyCredentials as $index => $credential): $created = (int)($credential['created_at'] ?? 0); $label = 'Passkey ' . ($index + 1); $credentialId = (string)($credential['credential_id'] ?? ''); ?>
                <div style="border:1px solid #e9ecef;border-radius:10px;padding:16px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;"><div style="min-width:0;"><strong><?php echo htmlspecialchars($label, ENT_QUOTES, 'UTF-8'); ?></strong><div style="font-size:13px;color:#777;margin-top:4px;">Added <?php echo $created > 0 ? htmlspecialchars(date('j M Y, H:i', $created), ENT_QUOTES, 'UTF-8') : 'date unavailable'; ?></div><div style="font-size:11px;color:#aaa;margin-top:3px;overflow:hidden;text-overflow:ellipsis;max-width:430px;">Credential: <?php echo htmlspecialchars(substr($credentialId, 0, 18) . (strlen($credentialId) > 18 ? '…' : ''), ENT_QUOTES, 'UTF-8'); ?></div></div><button type="button" class="btn btn-primary remove-passkey" data-credential="<?php echo htmlspecialchars($credentialId, ENT_QUOTES, 'UTF-8'); ?>" <?php echo count($passkeyCredentials) <= 1 ? 'disabled title="Keep at least one passkey registered"' : ''; ?>>Remove</button></div>
            <?php endforeach; ?>
        <?php endif; ?>
        <div style="padding:18px;border-radius:10px;background:#f8f9fa;border:1px solid #e9ecef;margin-top:16px;"><h4 style="margin-top:0;">Add another device</h4><p style="font-size:14px;color:#666;">Register another passkey on your phone, Mac, tablet, or another trusted device. Each passkey gets its own protected copy of your existing vault key.</p><a href="passkey_setup.php?add=1" class="btn btn-primary" style="display:inline-block;text-decoration:none;">＋ Add Another Passkey</a></div>
        <p style="font-size:13px;color:#777;margin-top:18px;">SentryIQ will not let you remove the last registered passkey. If you lose access to a device, use the password recovery route to regain access and register a replacement passkey.</p>
    </div>

    <div class="form-box" style="margin-top:20px;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:15px;gap:10px;flex-wrap:wrap;"><h3 style="margin:0;">🔐 System Log</h3><span style="font-size:12px;color:#777;"><?php echo count(read_security_log()); ?> events</span></div><?php $securityEvents = read_security_log(); ?><?php if (empty($securityEvents)): ?><p style="text-align:center;padding:20px;color:#777;">No security events have been recorded yet.</p><?php else: ?><div class="security-log-table" style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:12px;"><thead><tr style="background:#e9ecef;text-align:left;"><th style="padding:9px;">Date / Time</th><th style="padding:9px;">Event</th><th style="padding:9px;">User</th><th style="padding:9px;">IP Address</th><th style="padding:9px;">User Agent</th></tr></thead><tbody><?php foreach ($securityEvents as $event): ?><tr style="border-bottom:1px solid #eee;"><td style="padding:9px;white-space:nowrap;"><?php echo htmlspecialchars($event['timestamp'] ?? ''); ?></td><td style="padding:9px;font-weight:bold;"><?php echo htmlspecialchars($event['event'] ?? ''); ?></td><td style="padding:9px;"><?php echo htmlspecialchars($event['username'] ?? 'unknown'); ?></td><td style="padding:9px;"><?php echo htmlspecialchars($event['ip'] ?? 'unknown'); ?></td><td style="padding:9px;max-width:240px;word-break:break-word;color:#666;"><?php echo htmlspecialchars($event['user_agent'] ?? 'unknown'); ?></td></tr><?php endforeach; ?></tbody></table></div><div class="security-log-list"><?php foreach ($securityEvents as $event): ?><div class="security-log-card"><div class="security-log-card-header"><span class="security-log-event"><?php echo htmlspecialchars($event['event'] ?? ''); ?></span><span class="security-log-time"><?php echo htmlspecialchars($event['timestamp'] ?? ''); ?></span></div><div class="security-log-field"><span class="security-log-label">User</span><span class="security-log-value"><?php echo htmlspecialchars($event['username'] ?? 'unknown'); ?></span></div><div class="security-log-field"><span class="security-log-label">IP Address</span><span class="security-log-value"><?php echo htmlspecialchars($event['ip'] ?? 'unknown'); ?></span></div><div class="security-log-field"><span class="security-log-label">User Agent</span><span class="security-log-value"><?php echo htmlspecialchars($event['user_agent'] ?? 'unknown'); ?></span></div></div><?php endforeach; ?></div><?php endif; ?></div>
</div>

